// Elevated view of a rugged ocean shore — Direct 2D painting
const W = 1200, H = 800;
ctx.fillStyle = '#d9dee2';
ctx.fillRect(0, 0, W, H);

// ---------- noise helpers ----------
function hash(x, y) {
  let h = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
  return h - Math.floor(h);
}
function vnoise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash(xi, yi), b = hash(xi + 1, yi);
  const c = hash(xi, yi + 1), d = hash(xi + 1, yi + 1);
  return a * (1 - u) * (1 - v) + b * u * (1 - v) + c * (1 - u) * v + d * u * v;
}
function fbm(x, y, oct = 4) {
  let s = 0, a = 0.5, f = 1;
  for (let i = 0; i < oct; i++) { s += a * vnoise(x * f, y * f); f *= 2.07; a *= 0.5; }
  return s;
}
function ridged(x, y, oct = 4) {
  let s = 0, a = 0.5, f = 1;
  for (let i = 0; i < oct; i++) {
    const n = 1 - Math.abs(vnoise(x * f, y * f) * 2 - 1);
    s += a * n * n; f *= 2.1; a *= 0.5;
  }
  return s;
}

// ---------- sky (upper quarter) ----------
const skyH = H * 0.26;
const skyGrad = ctx.createLinearGradient(0, 0, 0, skyH);
skyGrad.addColorStop(0, '#ccd4da');
skyGrad.addColorStop(0.55, '#dde3e6');
skyGrad.addColorStop(1, '#e8ebeb');
ctx.fillStyle = skyGrad;
ctx.fillRect(0, 0, W, skyH + 4);

// soft cloud bands
for (let i = 0; i < 220; i++) {
  const y = rng() * skyH * 0.95;
  const x = rng() * W;
  const w = 80 + rng() * 220;
  const h = 4 + rng() * 14;
  const t = y / skyH;
  const g = ctx.createLinearGradient(x, y, x, y + h);
  const a = 0.04 + 0.05 * (1 - t);
  g.addColorStop(0, `rgba(180,190,198,${a})`);
  g.addColorStop(1, 'rgba(200,208,214,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.ellipse(x, y, w, h, 0, 0, Math.PI * 2); ctx.fill();
}

// ---------- horizon haze ----------
const hz = skyH;
const hzGrad = ctx.createLinearGradient(0, hz - 30, 0, hz + 70);
hzGrad.addColorStop(0, 'rgba(220,226,228,0.9)');
hzGrad.addColorStop(0.35, 'rgba(200,214,216,0.55)');
hzGrad.addColorStop(1, 'rgba(120,160,168,0)');
ctx.fillStyle = hzGrad;
ctx.fillRect(0, hz - 30, W, 100);

// distant sea base — deep teal to turquoise along diagonal
ctx.save();
ctx.beginPath();
ctx.moveTo(0, hz);
ctx.lineTo(W, hz);
ctx.lineTo(W, H);
ctx.lineTo(0, H);
ctx.closePath();
ctx.clip();

// base gradient aligned to diagonal coast
const diagAng = Math.atan2(H - hz, W * 0.55);
const dg = ctx.createLinearGradient(W * 0.9, hz + 10, W * 0.1, H);
dg.addColorStop(0, '#123b47');
dg.addColorStop(0.35, '#18606e');
dg.addColorStop(0.65, '#2b8a8f');
dg.addColorStop(1, '#4fbfb2');
ctx.fillStyle = dg;
ctx.fillRect(0, hz, W, H - hz);

// correlated color field — shallow turquoise patches near far coast
for (let i = 0; i < 60; i++) {
  const cx = rng() * W;
  const cy = hz + 40 + rng() * (H - hz - 40);
  const rr = 60 + rng() * 180;
  const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, rr);
  const pick = rng();
  if (pick < 0.5) {
    g.addColorStop(0, `rgba(90,200,190,${0.06 + rng() * 0.08})`);
  } else {
    g.addColorStop(0, `rgba(8,50,66,${0.08 + rng() * 0.1})`);
  }
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.ellipse(cx, cy, rr * 1.5, rr * 0.7, diagAng, 0, Math.PI * 2); ctx.fill();
}

// ---------- sea strokes (directional short strokes) ----------
const seaTop = hz + 6;
for (let i = 0; i < 5200; i++) {
  const x = rng() * W;
  const y = seaTop + rng() * (H - seaTop);
  const depth = (y - seaTop) / (H - seaTop);
  // direction field — roughly along wave fronts, slight swirl
  const n = fbm(x * 0.006, y * 0.006, 3);
  const ang = diagAng + (n - 0.5) * 0.9 + Math.sin(x * 0.004 + y * 0.002) * 0.35;
  const len = 2.5 + rng() * 6 + depth * 3;
  const light = fbm(x * 0.01 + 10, y * 0.01 + 5, 3);
  const a = 0.10 + 0.20 * light * (0.4 + depth * 0.6);
  // color: deep teal in far/deep regions, bright turquoise near diagonal
  const tealMix = depth * 0.7 + n * 0.3;
  let col;
  if (tealMix < 0.4) col = `rgba(150,215,210,${a})`;
  else if (tealMix < 0.7) col = `rgba(110,190,185,${a})`;
  else col = `rgba(200,235,225,${a * 0.8})`;
  ctx.strokeStyle = col;
  ctx.lineWidth = 0.7 + rng() * 1.1;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x + Math.cos(ang) * len, y + Math.sin(ang) * len);
  ctx.stroke();
}

// ---------- sweeping wave fronts ----------
// Each front: a base curve perturbed, body translucent green, foam lace
function waveFront(yBase, sweep, foamDensity, seed) {
  // build curve points
  const pts = [];
  const N = 90;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const x = t * W;
    const baseY = yBase + sweep * Math.sin(t * Math.PI * 1.2 + seed) + (t - 0.5) * 60;
    const nn = fbm(x * 0.008 + seed * 10, yBase * 0.01, 4);
    const y = baseY + (nn - 0.5) * 70;
    pts.push({ x, y });
  }
  // body
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) {
    const p = pts[i], pp = pts[i - 1];
    ctx.quadraticCurveTo((p.x + pp.x) / 2, (p.y + pp.y) / 2, p.x, p.y);
  }
  ctx.lineTo(W, H);
  ctx.lineTo(0, H);
  ctx.closePath();
  ctx.clip();
  const bodyGrad = ctx.createLinearGradient(0, yBase - 40, 0, yBase + 120);
  bodyGrad.addColorStop(0, 'rgba(120,220,195,0.30)');
  bodyGrad.addColorStop(0.5, 'rgba(60,170,160,0.22)');
  bodyGrad.addColorStop(1, 'rgba(20,90,110,0)');
  ctx.fillStyle = bodyGrad;
  ctx.fillRect(0, yBase - 60, W, 200);
  ctx.restore();

  // foam band along crest
  const foamPts = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const x = t * W;
    const baseY = yBase + sweep * Math.sin(t * Math.PI * 1.2 + seed) + (t - 0.5) * 60;
    const nn = fbm(x * 0.008 + seed * 10, yBase * 0.01, 4);
    const y = baseY + (nn - 0.5) * 70;
    foamPts.push({ x, y });
  }
  // lace foam: ridged mask along band
  const bandTop = yBase - 70, bandBot = yBase + 90;
  for (let i = 0; i < foamDensity; i++) {
    const x = rng() * W;
    const yb = bandTop + rng() * (bandBot - bandTop);
    // distance from curve — approximate by sampling nearby point
    let minD = 999, cy = 0;
    for (let k = 0; k < foamPts.length; k += 3) {
      const dx = foamPts[k].x - x, dy = foamPts[k].y - yb;
      const d = dx * dx + dy * dy;
      if (d < minD) { minD = d; cy = foamPts[k].y; }
    }
    const dist = Math.sqrt(minD);
    if (dist > 55) continue;
    const r = ridged(x * 0.05, yb * 0.05, 3);
    if (r < 0.55) continue;
    const alpha = 0.35 + 0.5 * (r - 0.55) / 0.45 * (1 - dist / 55);
    const sz = 0.9 + rng() * 2.6 * (1 - dist / 70);
    ctx.fillStyle = `rgba(252,254,252,${alpha})`;
    ctx.beginPath();
    ctx.arc(x, yb, sz, 0, Math.PI * 2);
    ctx.fill();
  }
  // branching threads
  for (let i = 0; i < 40; i++) {
    const idx = Math.floor(rng() * foamPts.length);
    const p = foamPts[idx];
    let x = p.x, y = p.y;
    let ang = Math.atan2(pts[Math.min(idx + 3, pts.length - 1)].y - p.y, pts[Math.min(idx + 3, pts.length - 1)].x - p.x) + Math.PI / 2;
    ctx.strokeStyle = 'rgba(250,254,250,0.5)';
    ctx.lineWidth = 0.8 + rng() * 1.4;
    ctx.beginPath();
    ctx.moveTo(x, y);
    const steps = 8 + Math.floor(rng() * 10);
    for (let s = 0; s < steps; s++) {
      x += Math.cos(ang) * (2 + rng() * 4);
      y += Math.sin(ang) * (1 + rng() * 3) + (rng() - 0.5) * 2;
      ang += (rng() - 0.5) * 0.4;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
}
// three fronts, from far to foreground
waveFront(hz + 90, 24, 900, 0.3);
waveFront(hz + 280, 40, 1500, 2.1);
waveFront(hz + 490, 55, 2200, 4.7);

ctx.restore();

// ---------- rocky coastline (diagonal from lower-left to mid-right) ----------
// Wet rocks — jagged polygons
function makeRock(cx, cy, s, seed) {
  const pts = [];
  const n = 7 + Math.floor(rng() * 5);
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const r = s * (0.6 + rng() * 0.5);
    const nx = cx + Math.cos(a) * r + (vnoise(seed + i * 3.1, 0.5) - 0.5) * s * 0.3;
    const ny = cy + Math.sin(a) * r * 0.85 + (vnoise(0.5, seed + i * 2.7) - 0.5) * s * 0.25;
    pts.push({ x: nx, y: ny });
  }
  // paint body with cool/warm mottling clipped to polygon
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
  ctx.closePath();
  ctx.clip();
  // base
  const bg = ctx.createLinearGradient(cx - s, cy - s, cx + s, cy + s);
  const cool = rng() < 0.5;
  bg.addColorStop(0, cool ? '#3a4448' : '#4a423a');
  bg.addColorStop(1, cool ? '#2a3032' : '#2e2823');
  ctx.fillStyle = bg;
  ctx.fillRect(cx - s * 1.2, cy - s * 1.2, s * 2.4, s * 2.4);
  // mottling
  for (let i = 0; i < 40; i++) {
    const x = cx + (rng() - 0.5) * s * 2;
    const y = cy + (rng() - 0.5) * s * 2;
    const r = 2 + rng() * s * 0.4;
    const warm = rng() < 0.45;
    const a = 0.15 + rng() * 0.3;
    ctx.fillStyle = warm ? `rgba(120,95,70,${a})` : `rgba(70,90,100,${a})`;
    ctx.beginPath(); ctx.ellipse(x, y, r, r * 0.8, rng() * 3, 0, Math.PI * 2); ctx.fill();
  }
  // wet highlights — narrow along upper edges
  ctx.strokeStyle = 'rgba(200,220,225,0.55)';
  ctx.lineWidth = 1.2;
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i], b = pts[(i + 1) % pts.length];
    if (a.y < cy && rng() < 0.6) {
      ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
    }
  }
  ctx.restore();
  // shoreline dark edge
  ctx.strokeStyle = 'rgba(20,30,34,0.6)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
  ctx.closePath(); ctx.stroke();
}

// place rocks along diagonal coastline
function coastY(x) {
  // lower-left to mid-right diagonal
  const t = x / W;
  return H - 60 - t * 360 + Math.sin(t * 6) * 30 + (fbm(x * 0.008, 3.3, 3) - 0.5) * 90;
}
// rock cluster masses
const rockSeeds = [];
for (let i = 0; i < 26; i++) {
  const x = (i / 25) * W * 1.05 + (rng() - 0.5) * 40;
  const yBase = coastY(x);
  const y = yBase + (rng() - 0.5) * 40;
  const s = 18 + rng() * 55 + (x > W * 0.4 && x < W * 0.85 ? 25 : 0);
  rockSeeds.push({ x, y, s, seed: rng() * 100 });
}
rockSeeds.sort((a, b) => a.y - b.y);
for (const r of rockSeeds) makeRock(r.x, r.y, r.s, r.seed);

// foam bending around rocks — lace near rock bases
for (const r of rockSeeds) {
  const n = 30 + Math.floor(r.s * 0.8);
  for (let i = 0; i < n; i++) {
    const a = rng() * Math.PI * 2;
    const rr = r.s * (0.7 + rng() * 0.8);
    const x = r.x + Math.cos(a) * rr;
    const y = r.y + Math.sin(a) * rr * 0.7 + r.s * 0.3;
    const v = ridged(x * 0.06, y * 0.06, 2);
    if (v < 0.5) continue;
    ctx.fillStyle = `rgba(248,252,250,${0.25 + v * 0.4})`;
    ctx.beginPath(); ctx.arc(x, y, 0.8 + rng() * 2.2, 0, Math.PI * 2); ctx.fill();
  }
}

// ---------- foreground curling wave focal point (lower-left/center) ----------
// a large sweeping curl built from layered arcs
ctx.save();
const fx = W * 0.32, fy = H * 0.86;

// curl body — stacked translucent green arcs
for (let k = 0; k < 8; k++) {
  const scale = 1 - k * 0.09;
  const rx = 260 * scale, ry = 120 * scale;
  const g = ctx.createLinearGradient(fx - rx, fy, fx + rx, fy - ry * 2);
  g.addColorStop(0, `rgba(30,120,120,${0.22 - k * 0.02})`);
  g.addColorStop(0.6, `rgba(80,200,180,${0.28 - k * 0.02})`);
  g.addColorStop(1, `rgba(160,240,220,${0.15 - k * 0.015})`);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(fx, fy, rx, ry, -0.25, Math.PI, Math.PI * 2);
  ctx.fill();
}

// main curling crest — sweeping curve with dense foam lace
const curlPts = [];
const cn = 120;
for (let i = 0; i <= cn; i++) {
  const t = i / cn;
  // parametric curl: sweeping over the top from left, curling down right
  const ang = Math.PI + t * Math.PI * 1.15;
  const rad = 230 - t * 60;
  const x = fx + Math.cos(ang) * rad * 1.25 + t * 80;
  const y = fy - Math.sin(ang) * rad * 0.85 - t * 40;
  curlPts.push({ x, y });
}
// foam body along the crest
for (let i = 0; i < 1400; i++) {
  const t = rng();
  const idx = Math.floor(t * (cn - 1));
  const p = curlPts[idx];
  const off = (rng() - 0.5) * 40;
  const x = p.x + off + (rng() - 0.5) * 10;
  const y = p.y + off * 0.4 + (rng() - 0.5) * 8;
  const r = ridged(x * 0.05, y * 0.05, 3);
  if (r < 0.5) continue;
  const alpha = 0.3 + r * 0.5;
  const sz = 0.8 + rng() * 2.4;
  ctx.fillStyle = `rgba(252,254,252,${alpha})`;
  ctx.beginPath(); ctx.arc(x, y, sz, 0, Math.PI * 2); ctx.fill();
}
// branching thread lace on the curl
for (let i = 0; i < 60; i++) {
  const idx = Math.floor(rng() * curlPts.length);
  const p = curlPts[idx];
  let x = p.x, y = p.y;
  let ang = Math.atan2(curlPts[Math.min(idx + 4, cn)].y - p.y, curlPts[Math.min(idx + 4, cn)].x - p.x);
  ctx.strokeStyle = `rgba(250,254,250,${0.35 + rng() * 0.4})`;
  ctx.lineWidth = 0.6 + rng() * 1.4;
  ctx.beginPath(); ctx.moveTo(x, y);
  const steps = 10 + Math.floor(rng() * 12);
  for (let s = 0; s < steps; s++) {
    ang += (rng() - 0.5) * 0.5;
    x += Math.cos(ang) * (2 + rng() * 3);
    y += Math.sin(ang) * (2 + rng() * 3);
    ctx.lineTo(x, y);
  }
  ctx.stroke();
}
// dark inner curl shadow — gives depth to the face of the wave
const shadow = ctx.createRadialGradient(fx + 120, fy - 120, 10, fx + 120, fy - 120, 130);
shadow.addColorStop(0, 'rgba(8,40,50,0.55)');
shadow.addColorStop(1, 'rgba(8,40,50,0)');
ctx.fillStyle = shadow;
ctx.beginPath(); ctx.ellipse(fx + 120, fy - 120, 130, 90, -0.4, 0, Math.PI * 2); ctx.fill();

// crisp lace at lip of the curl (thin arc line with holes)
for (let i = 0; i < 500; i++) {
  const t = rng();
  const idx = Math.floor(t * (cn - 1));
  const p = curlPts[idx];
  const x = p.x + (rng() - 0.5) * 6;
  const y = p.y + (rng() - 0.5) * 6;
  const v = vnoise(x * 0.08, y * 0.08);
  if (v < 0.55) continue;
  ctx.fillStyle = `rgba(255,255,252,${0.6 + v * 0.4})`;
  ctx.beginPath(); ctx.arc(x, y, 0.9 + rng() * 1.8, 0, Math.PI * 2); ctx.fill();
}
ctx.restore();

// ---------- spray / fine coastal spume ----------
for (let i = 0; i < 500; i++) {
  // concentrated near close wave and rock collisions
  let x, y;
  const pick = rng();
  if (pick < 0.4) {
    x = fx + (rng() - 0.5) * 320;
    y = fy - 180 + (rng() - 0.5) * 220;
  } else if (pick < 0.7) {
    const r = rockSeeds[Math.floor(rng() * rockSeeds.length)];
    x = r.x + (rng() - 0.5) * 100;
    y = r.y + (rng() - 0.5) * 80;
  } else {
    x = rng() * W;
    y = hz + rng() * 200;
  }
  if (y < hz - 20 || y > H - 40) continue;
  const a = 0.15 + rng() * 0.35;
  ctx.fillStyle = `rgba(240,248,246,${a})`;
  ctx.beginPath(); ctx.arc(x, y, 0.5 + rng() * 1.3, 0, Math.PI * 2); ctx.fill();
}

// ---------- thin atmospheric haze bands near horizon ----------
for (let i = 0; i < 6; i++) {
  const y = hz + 10 + i * 14 + rng() * 6;
  ctx.fillStyle = `rgba(205,218,220,${0.06 + rng() * 0.08})`;
  ctx.fillRect(0, y, W, 2 + rng() * 4);
}

// ---------- foreground dark water shadow / vignette base ----------
const vg = ctx.createLinearGradient(0, H - 120, 0, H);
vg.addColorStop(0, 'rgba(6,30,40,0)');
vg.addColorStop(1, 'rgba(4,18,26,0.5)');
ctx.fillStyle = vg;
ctx.fillRect(0, H - 120, W, 120);

// slight overall cool light wash for overcast
ctx.fillStyle = 'rgba(200,218,222,0.05)';
ctx.fillRect(0, 0, W, H);
